    c = cart.Cart()
    with pytest.raises(ValueError):
        c.add_item("banana", -1.0, 2)
    with pytest.raises(ValueError):
        c.add_item("orange", 3.0, 0)
    with pytest.raises(ValueError):
        c.add_item("orange", 3.0, -5)

