    c.add_item("apple", 2.0, 5)  # subtotal 10
    c.remove_item("apple", 3)
    assert c.items() == {"apple": 2}
    # Remove remaining quantity
    c.remove_item("apple", 2)
    assert "apple" not in c.items()

