    ([("item", 500.0, 1)], None, False, 560.00),            # 500 + 60
    ([("item", 200.0, 1)], "SAVE10", False, 240.00),      # 180 + 60
    ([("item", 200.0, 1)], "SAVE10", True, 210.00),       # 180 + 30
    ([("item", 99.0, 1)], "SAVE5", False, 154.05),        # 94.05 + 60
    ([("item", 800.0, 1)], "SAVE10", False, 780.00),      # 720 + 60
